<script setup lang="ts">import {reactive,ref,onMounted,onUnmounted} from 'vue';import {api,errorMessage}from'../api';import PageHeader from'../components/PageHeader.vue';import Modal from'../components/Modal.vue';import DataTable from'../components/DataTable.vue';import StatusBadge from'../components/StatusBadge.vue';import{Plus}from'lucide-vue-next';const rows=ref<any[]>([]),open=ref(false),error=ref('');const form=reactive({name:'',email:'',password:'',role:'tenant_admin'});const cols=[{key:'name',label:'Nome'},{key:'email',label:'E-mail'},{key:'status',label:'Situação'},{key:'is_platform_admin',label:'Plataforma'}];async function load(){rows.value=(await api.get('/users')).data}async function save(){try{await api.post('/users',form);open.value=false;await load()}catch(e){error.value=errorMessage(e)}}onMounted(()=>{load();window.addEventListener('tenant-changed',load)});onUnmounted(()=>window.removeEventListener('tenant-changed',load))</script><template><PageHeader title="Usuários e permissões" subtitle="Controle acessos e funções por cliente e CNPJ"><button class="btn primary" @click="open=true"><Plus :size="16"/>Novo usuário</button></PageHeader><section class="panel"><DataTable :columns="cols" :rows="rows"><template #cell-status="{value}"><StatusBadge :status="value"/></template><template #cell-is_platform_admin="{value}">{{value?'Sim':'Não'}}</template></DataTable></section><Modal :open="open" title="Novo usuário" @close="open=false"><form class="form-grid" @submit.prevent="save"><label>Nome<input v-model="form.name" required/></label><label>E-mail<input v-model="form.email" type="email" required/></label><label>Senha<input v-model="form.password" type="password" minlength="10" required/></label><label>Perfil<select v-model="form.role"><option value="tenant_owner">Proprietário</option><option value="tenant_admin">Administrador</option><option value="fiscal_manager">Gestor fiscal</option><option value="fiscal_operator">Operador fiscal</option><option value="auditor">Auditor</option></select></label><div v-if="error" class="alert danger span-2">{{error}}</div><div class="form-actions span-2"><button class="btn primary">Salvar</button></div></form></Modal></template>
